## The Bug

There are actually two issues:

1. **Off-by-one comparison**: `decoded.exp < Date.now() / 1000` uses strict less-than, so a token where `exp === now` passes through — it should be `<=`.

2. **Redundant manual check**: `jwt.verify()` already throws `TokenExpiredError` for expired tokens (using `>=` internally), so the manual check runs dead code after a successful verify — except it uses the wrong operator, creating a gap.

The cleanest fix is to remove the redundant manual check and handle specific JWT error types properly:

```javascript
const jwt = require('jsonwebtoken');

function authMiddleware(req, res, next) {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'No token provided' });
  }

  try {
    // jwt.verify already rejects tokens where exp <= now (including exact match)
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (err) {
    if (err.name === 'TokenExpiredError') {
      return res.status(401).json({ error: 'Token expired' });
    }
    if (err.name === 'JsonWebTokenError') {
      return res.status(401).json({ error: 'Invalid token' });
    }
    if (err.name === 'NotBeforeError') {
      return res.status(401).json({ error: 'Token not yet valid' });
    }
    // Unexpected errors (e.g. bad secret env var) shouldn't leak internals
    console.error('Auth middleware error:', err);
    return res.status(500).json({ error: 'Authentication error' });
  }
}

module.exports = authMiddleware;
```

**Key changes:**
- Removed the manual `decoded.exp` check — `jwt.verify()` handles expiry correctly including the exact-match case
- Split the catch into specific JWT error types for accurate client responses
- Added a fallthrough for unexpected errors (misconfigured secret, etc.) that logs server-side and returns 500 rather than leaking internals
